 if($action==='ensure-test-account'){$email='test@core.local';$password='CoreTest2026!';$id=null;foreach($accounts as $key=>$a)if(is_array($a)&&strtolower((string)($a['email']??''))===$email){$id=(string)$key;break;}$created=$id===null;if($created)$id='usr_'.bin2hex(random_bytes(12));$accounts[$id]=array_merge(is_array($accounts[$id]??null)?$accounts[$id]:[],['id'=>$id,'email'=>$email,'password_hash'=>password_hash($password,PASSWORD_DEFAULT),'created_at'=>$accounts[$id]['created_at']??gmdate('c'),'status'=>'active','account_type'=>'test']);save_accounts($file,$accounts);echo json_encode(['ok'=>true,'message'=>$created?'Test account created. Sign in at /player/account.php with test@core.local and the displayed test password.':'Test account password reset and account re-enabled.']);exit;}
 if($action==='update'){$id=(string)($in['id']??'');if(!isset($accounts[$id])||!is_array($accounts[$id])){http_response_code(404);echo json_encode(['ok'=>false,'error'=>['message'=>'Account not found.']]);exit;}$email=strtolower(trim((string)($in['email']??'')));$status=(string)($in['status']??'active');$type=trim((string)($in['account_type']??'player'));$created=trim((string)($in['created_at']??($accounts[$id]['created_at']??'')));$password=(string)($in['new_password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>254||!in_array($status,['active','locked','banned','disabled'],true)||$type===''||strlen($type)>80){http_response_code(400);echo json_encode(['ok'=>false,'error'=>['message'=>'Enter a valid email, account type, and supported access status.']]);exit;}foreach($accounts as $otherId=>$other)if((string)$otherId!==$id&&is_array($other)&&strtolower((string)($other['email']??''))===$email){http_response_code(409);echo json_encode(['ok'=>false,'error'=>['message'=>'Another account already uses that email.']]);exit;}if($password!==''&&(strlen($password)<10||strlen($password)>4096)){http_response_code(400);echo json_encode(['ok'=>false,'error'=>['message'=>'New password must be 10–4096 characters.']]);exit;}$accounts[$id]['email']=$email;$accounts[$id]['status']=$status;$accounts[$id]['account_type']=$type;$accounts[$id]['created_at']=$created;if($password!=='')$accounts[$id]['password_hash']=password_hash($password,PASSWORD_DEFAULT);save_accounts($file,$accounts);$savedRaw=file_get_contents($file);$savedAccounts=json_decode(is_string($savedRaw)?$savedRaw:'',true);if(!is_array($savedAccounts)||!isset($savedAccounts[$id])||!is_array($savedAccounts[$id])){http_response_code(500);echo json_encode(['ok'=>false,'error'=>['message'=>'Account update could not be verified after saving.']]);exit;}if($password!==''&&(!isset($savedAccounts[$id]['password_hash'])||!password_verify($password,(string)$savedAccounts[$id]['password_hash']))){http_response_code(5